@router.post("/import/groww-csv")
async def import_groww_csv(file: UploadFile = File(...), background_tasks: BackgroundTasks = None):
    if file.size > 10 * 1024 * 1024:
        raise HTTPException(status_code=413, detail="File size limit exceeded")
